-- Seed data: the 94 characters that used to be hardcoded in api/index.py.
-- Run this AFTER schema.sql, in the Supabase SQL Editor.

on conflict (id) do nothing;

-- The ids above were inserted manually, so move the identity counter past them.
-- Without this, the first POST would try id 1 again and fail with a duplicate key.
select setval(
  pg_get_serial_sequence('public.characters', 'id'),
  (select max(id) from public.characters)
);
